const snippets={"Python": ["from typing import List", "", "class Solution:", "", "    def canPartition(self, nums: List[int]) -> bool:", "        (m, mod) = divmod(sum(nums), 2)", "        if mod:", "            return False", "        n = len(nums)", "        f = [[False] * (m + 1) for _ in range(n + 1)]", "        f[0][0] = True", "        for (i, x) in enumerate(nums, 1):", "            for j in range(m + 1):", "                f[i][j] = f[i - 1][j] or (j >= x and f[i - 1][j - x])", "        return f[n][m]"], "Java": ["import java.util.*;", "class Solution {", "    public boolean canPartition(int[] nums) {", "        // int s = Arrays.stream(nums).sum();", "        int s = 0;", "        for (int x : nums) {", "            s += x;", "        }", "        if (s % 2 == 1) {", "            return false;", "        }", "        int n = nums.length;", "        int m = s >> 1;", "        boolean[][] f = new boolean[n + 1][m + 1];", "        f[0][0] = true;", "        for (int i = 1; i <= n; ++i) {", "            int x = nums[i - 1];", "            for (int j = 0; j <= m; ++j) {", "                f[i][j] = f[i - 1][j] || (j >= x && f[i - 1][j - x]);", "            }", "        }", "        return f[n][m];", "    }", "}"]};
